def minimum_abs_difference(arr):
    n = len(arr)
    min_diff = float('inf')
    for i in range(n):
        for j in range(i + 1, n):
            min_diff = min(min_diff, abs(arr[i] - arr[j]))

    result = []
    for i in range(n):
        for j in range(i + 1, n):
            if abs(arr[i] - arr[j]) == min_diff:
                a, b = min(arr[i], arr[j]), max(arr[i], arr[j])
                result.append([a, b])

    result.sort()
    return result


if __name__ == "__main__":
    print(minimum_abs_difference([4, 2, 1, 3]))
    print(minimum_abs_difference([1, 3, 6, 10, 15]))

