import java.util.*;

public class Main {
    static List<List<Integer>> minimumAbsDifference(int[] arr) {
        int n = arr.length;
        int minDiff = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                minDiff = Math.min(minDiff, Math.abs(arr[i] - arr[j]));
            }
        }

        List<List<Integer>> result = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (Math.abs(arr[i] - arr[j]) == minDiff) {
                    int a = Math.min(arr[i], arr[j]), b = Math.max(arr[i], arr[j]);
                    result.add(Arrays.asList(a, b));
                }
            }
        }
        result.sort((p, q) -> p.get(0) - q.get(0));
        return result;
    }

    public static void main(String[] args) {
        System.out.println(minimumAbsDifference(new int[]{4, 2, 1, 3}));
        System.out.println(minimumAbsDifference(new int[]{1, 3, 6, 10, 15}));
    }
}

