    min_diff = min(sorted_arr[i] - sorted_arr[i - 1] for i in range(1, len(sorted_arr)))

    result = []
    for i in range(1, len(sorted_arr)):
        if sorted_arr[i] - sorted_arr[i - 1] == min_diff:
            result.append([sorted_arr[i - 1], sorted_arr[i]])

    return result


